const items = $input.all();
const total = items.length;
if (total === 0) {
  return [{ json: { 
    subject: 'Sin productos con stock bajo', 
    html: '<p>Todos los productos estan dentro de su stock minimo.</p>', 
    text: 'Todos los productos estan dentro de su stock minimo.' 
  } }];
}
let rows = items.map(p => {
  const stock = Number(p.json.stock) || 0;
  const min = Number(p.json.stock_minimo) || 0;
  const falta = min - stock;
  const color = falta > 0 ? '#fff3cd' : '#f8d7da';
  return `<tr style="background:${color}">
    <td style="padding:6px 10px;border-bottom:1px solid #ddd;">${p.json.codigo||''}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #ddd;">${p.json.nombre||''}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:center;">${p.json.categoria||'-'}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:center;font-weight:700;color:${falta>0?'#dc3545':'#ffc107'};">${stock}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:center;">${min}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:center;font-weight:700;color:#dc3545;">${falta>0?falta:0}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:right;">$${stock * (Number(p.json.precio_compra)||0)}</td>
  </tr>`;
}).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:Arial,sans-serif;font-size:14px;color:#333;">
  <h2 style="color:#dc3545;">Alerta de Stock Bajo</h2>
  <p>Se detectaron <strong>${total}</strong> producto(s) por debajo de su stock minimo:</p>
  <table style="border-collapse:collapse;width:100%;max-width:800px;">
    <thead><tr style="background:#343a40;color:#fff;">
      <th style="padding:8px 10px;text-align:left;">Codigo</th>
      <th style="padding:8px 10px;text-align:left;">Producto</th>
      <th style="padding:8px 10px;text-align:center;">Categoria</th>
      <th style="padding:8px 10px;text-align:center;">Stock</th>
      <th style="padding:8px 10px;text-align:center;">Minimo</th>
      <th style="padding:8px 10px;text-align:center;">Faltan</th>
      <th style="padding:8px 10px;text-align:right;">Valor</th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table>
  <p style="margin-top:16px;color:#666;font-size:12px;">Reporte automatico generado por el sistema de almacen.</p>
</body></html>`;
const text = `ALERTA DE STOCK BAJO

Se detectaron ${total} producto(s):

` +
  items.map(p => `- ${p.json.codigo} ${p.json.nombre}: Stock ${p.json.stock} / Min ${p.json.stock_minimo}`).join('
');
return [{ json: { subject: `Stock Bajo - ${total} producto(s)`, html, text } }];
